{
  "analysis": "Found the issue. The nginx.conf has a hardcoded server block that proxies everything to port 8080, and it does not include sites-enabled at all. Our noVNC site config was never loaded. I need to replace the nginx.conf with a proper configuration that serves noVNC static files and proxies WebSocket connections to websockify on port 6080.",
  "plan": "Write a new nginx.conf that serves noVNC from /usr/share/novnc on the root path and proxies /websockify to port 6080. Test the config, reload nginx, and verify with Python urllib.",
  "commands": [
    {
      "keystrokes": "cat > /etc/nginx/nginx.conf << 'EOF'
user  root;
worker_processes  1;

events {
    worker_connections 4096;
}

http {
    include       mime.types;
    default_type  application/octet-stream;

    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;

    keepalive_timeout 65;

    server {
        listen 80 default_server;
        server_name _;

        location / {
            root /usr/share/novnc;
            index vnc.html vnc_lite.html;
        }

        location /websockify {
            proxy_pass http://127.0.0.1:6080;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection "upgrade";
            proxy_set_header Host $host;
            proxy_read_timeout 3600s;
            proxy_send_timeout 3600s;
        }
    }
}
EOF
nginx -t && nginx -s reload
",
      "duration": 1.0
    },
    {
      "keystrokes": "python3 -c "
import urllib.request
try:
    resp = urllib.request.urlopen('http://127.0.0.1:80/')
    html = resp.read().decode(errors='replace')
    print('HTTP status:', resp.status)
    print('Contains VNC:', 'vnc' in html.lower())
    print('First 200 chars:', html[:200])
except Exception as e:
    print('Error:', e)
"
",
      "duration": 3.0
    }
  ]
}
